<?php
declare(strict_types=1);namespace Liberu\Accounting\ForecastsApi\Http\Controllers;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Routing\Controller;use Liberu\Accounting\Forecasts\Actions\{AddForecastLine,CreateForecast,DecideForecast,ReplaceActual,SubmitForecast};use Liberu\Accounting\Forecasts\Enums\ForecastStatus;use Liberu\Accounting\Forecasts\Models\Forecast;use Liberu\Accounting\Forecasts\Queries\ForecastQuery;use Liberu\Accounting\ForecastsApi\Http\Resources\ForecastResource;final class ForecastsController extends Controller {public function __construct(private readonly ForecastQuery $query){}public function index(Request $r):ForecastResource{$s=$r->filled('status')?ForecastStatus::from($r->string('status')->toString()):null;return new ForecastResource($this->query->paginate($r->integer('team_id')?:null,$s,$r->integer('per_page',25)));}public function store(Request $r,CreateForecast $a):ForecastResource{return new ForecastResource($a->handle($r->all()));}public function show(Forecast $forecast):ForecastResource{return new ForecastResource($forecast->load(['lines','assumptions','approvals','periods','actuals']));}public function line(Request $r,Forecast $forecast,AddForecastLine $a):ForecastResource{$d=$r->validate(['period_ref'=>'required|string|max:100','account_ref'=>'required|string|max:255','dimension_ref'=>'nullable|string|max:255','description'=>'required|string|max:1000','driver_ref'=>'nullable|string|max:255','forecast_value'=>'required|numeric','metadata'=>'nullable|array']);$a->handle($forecast,$d);return new ForecastResource($forecast->load('lines'));}public function submit(Forecast $forecast,SubmitForecast $a):ForecastResource{return new ForecastResource($a->handle($forecast));}public function decide(Request $r,Forecast $forecast,DecideForecast $a):ForecastResource{$d=$r->validate(['actor_ref'=>'required|string|max:255','approved'=>'required|boolean','comment'=>'nullable|string|max:5000']);return new ForecastResource($a->handle($forecast,$d['actor_ref'],(bool)$d['approved'],$d['comment']??null));}public function actual(Request $r,Forecast $forecast,ReplaceActual $a):ForecastResource{$d=$r->validate(['line_id'=>'nullable|integer','period_ref'=>'required|string|max:100','actual_value'=>'required|numeric|min:0','source_ref'=>'required|string|max:255','metadata'=>'nullable|array']);$a->handle($forecast,$d);return new ForecastResource($forecast->load(['lines','actuals']));}public function variance(Forecast $forecast,ForecastQuery $q):JsonResponse{return response()->json(['data'=>$q->variance($forecast)]);}}
